cd /Users/jose.bomfim/UFCG/2026.2/DEVIA/ciframe && python3 - <<'PY'
import collections
ARTISTA_ID,MUSICA_ID,ARTISTA,MUSICA,GENERO,POP,TOM,SEQ,CIFRA=range(9)
rows=[]
with open('data/top/dataset_final.csv') as f:
    f.readline()
    for line in f:
        line=line.replace('"','').replace('NA','')[:-1]
        m=line.split(',')
        if len(m)<9: continue
        cifra=[x for x in m[CIFRA].split(';') if x.strip()!=''] if m[CIFRA] else []
        seq=[x for x in m[SEQ].split(';') if x!='']
        rows.append((m[ARTISTA_ID]+'_'+m[MUSICA_ID], cifra, seq))
print("raw SEQ multi values:", collections.Counter(tuple(r[2]) for r in rows if len(r[2])>1).most_common(5))

seqs={'BmGDA':['Bm','G','D','A'],'CGAmF':['C','G','Am','F'],'EmG':['Em','G'],
      'CA7DmG7':['C','A7','Dm','G7'],'GmF':['Gm','F'],'CC7FFm':['C','C7','F','Fm']}

def contiguous(cifra, seq, ci=True):
    a=[c.lower() for c in cifra] if ci else cifra
    b=[c.lower() for c in seq] if ci else seq
    n=len(b)
    return any(a[i:i+n]==b for i in range(len(a)-n+1))

def subsequence(cifra, seq, ci=True):
    a=[c.lower() for c in cifra] if ci else cifra
    b=[c.lower() for c in seq] if ci else seq
    it=iter(a)
    return all(any(x==y for x in it) for y in b)

def subset(cifra, seq, ci=True):
    a={c.lower() for c in cifra} if ci else set(cifra)
    b={c.lower() for c in seq} if ci else set(seq)
    return b<=a

def hist_alg(cifra, seq, ci=True):
    s=';'.join(seq); a=';'.join(cifra)
    if ci: s=s.lower(); a=a.lower()
    if s in a:
        toks=set(s.split(';'))
        return all(l in toks for l in a.split(';'))
    return False

print(f"{'seq':10} {'tagged':>6} {'contig':>6} {'contigCS':>8} {'subseq':>6} {'subset':>6} {'hist':>5}  tagged&contig  contig&!tag")
for name,seq in seqs.items():
    tagged={r[0] for r in rows if str(list(seqs).index(name)) in r[2]}
    contig={r[0] for r in rows if contiguous(r[1],seq)}
    contigCS={r[0] for r in rows if contiguous(r[1],seq,False)}
    subseq={r[0] for r in rows if subsequence(r[1],seq)}
    subsetS={r[0] for r in rows if subset(r[1],seq)}
    hist={r[0] for r in rows if hist_alg(r[1],seq)}
    print(f"{name:10} {len(tagged):6} {len(contig):6} {len(contigCS):8} {len(subseq):6} {len(subsetS):6} {len(hist):5}  {len(tagged&contig):12}  {len(contig-tagged):10}")
    # recall of tagged by each
    for lbl,s in [('contig',contig),('contigCS',contigCS),('subseq',subseq),('subset',subsetS),('hist',hist)]:
        inter=len(tagged&s); rec=inter/len(tagged) if tagged else 0; prec=inter/len(s) if s else 0
        print(f"    {lbl:9} recall={rec:.3f} precision={prec:.3f} missing={len(tagged-s)} extra={len(s-tagged)}")
