        self.assertTrue(
            matching.vocabulario_contido(
                ["Bm", "G", "D", "A"], ["Bm", "G", "D", "A", "Em"]
            )
        )
        self.assertFalse(
            matching.vocabulario_contido(
                ["Bm", "G", "D", "A"], ["Bm", "G", "D"]
            )
        )

    def test_repeticao_na_sequencia(self):
        self.assertTrue(
            matching.musica_casa_sequencia(
                ["Bm", "G", "D", "A", "A"], ["Bm", "G", "D", "A", "A"]
            )
        )
        self.assertFalse(
            matching.musica_casa_sequencia(
                ["Bm", "G", "D", "A"], ["Bm", "G", "D", "A", "A"]
